//! LtHash tests (commonware `lthash/mod.rs` tests), checksums generated by commonware, and
//! the `lthash_operations` and `metamorph_lthash` fuzz targets.

const std = @import("std");
const testing = std.testing;
const codec = @import("codec");
const utils = @import("utils");
const fuzz = @import("fuzz.zig");
const lthash = @import("lthash.zig");
const Blake3 = @import("blake3.zig").Blake3;
const Sha256 = @import("sha256.zig").Sha256;

const LtHash = lthash.LtHash;

fn expect_checksum(expected_hex: []const u8, hash: *const LtHash) !void {
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, expected_hex);
    try testing.expectEqualSlices(u8, &expected, &hash.checksum().bytes);
}

test "lthash new, add, reset" {
    var hash = LtHash.init();
    try testing.expect(hash.is_zero());
    hash.add("hello");
    try testing.expect(!hash.is_zero());
    hash.reset();
    try testing.expect(hash.is_zero());
}

test "lthash commutativity, associativity, subtraction" {
    var forward = LtHash.init();
    forward.add("hello");
    forward.add("world");
    var backward = LtHash.init();
    backward.add("world");
    backward.add("hello");
    try testing.expect(forward.checksum().eql(backward.checksum()));

    var serial = LtHash.init();
    for ([_][]const u8{ "a", "b", "c" }) |item| serial.add(item);
    var combined = LtHash.init();
    var rest = LtHash.init();
    rest.add("b");
    rest.add("c");
    combined.add("a");
    combined.combine(&rest);
    try testing.expect(serial.checksum().eql(combined.checksum()));

    var hello = LtHash.init();
    hello.add("hello");
    var round_trip = LtHash.init();
    round_trip.add("hello");
    round_trip.add("world");
    round_trip.subtract("world");
    try testing.expect(hello.checksum().eql(round_trip.checksum()));
}

test "lthash empty checksum hashes zero elements" {
    var hasher = Blake3.init();
    for (0..lthash.elements) |_| hasher.update(&.{ 0, 0 });
    try testing.expect(LtHash.zero.checksum().eql(hasher.finalize()));
}

test "lthash snake is order independent" {
    var forward = LtHash.init();
    var backward = LtHash.init();
    for (0..100) |index| {
        var bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &bytes, @intCast(index), .little);
        forward.add(&bytes);
        std.mem.writeInt(u32, &bytes, @intCast(99 - index), .little);
        backward.add(&bytes);
    }
    try testing.expect(forward.checksum().eql(backward.checksum()));
}

test "lthash checksums match commonware" {
    try expect_checksum(
        "be2a8de3dcf46c94ce85cdc8e07ac308f4d8a95490d956c38d780fd610db0813",
        &LtHash.zero,
    );
    var hash = LtHash.init();
    hash.add("hello");
    try expect_checksum("4f9c1ab89ccd5ed0b6eb21936f99e598cf854b6db6c6773d0b51294618576455", &hash);

    // The encoding writes each element big-endian.
    const encoded = codec.encode_fixed(LtHash, hash);
    var prefix: [16]u8 = undefined;
    _ = try std.fmt.hexToBytes(&prefix, "8fea3d1686b39282445ec5918de5b34b");
    try testing.expectEqualSlices(u8, &prefix, encoded[0..16]);
    var encoded_hash: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(
        &encoded_hash,
        "16b654c181e9f1a332b35da57904f1d2fc064fb57e1b4da0b64fc9f0dcfe2670",
    );
    try testing.expectEqualSlices(u8, &encoded_hash, &Sha256.hash(&.{&encoded}).bytes);
    const decoded = try codec.decode(LtHash, testing.allocator, &encoded);
    try testing.expect(decoded.checksum().eql(hash.checksum()));

    hash.add("world");
    try expect_checksum("7d3790d32bba3ea1a17b9ff814c5aba238576404012fd4c03f6def65d1792712", &hash);

    var large = LtHash.init();
    large.add(&@as([10000]u8, @splat(0xab)));
    try expect_checksum("3115f1a674243a678e72e1ba77e0aa7df82adefbe18c7b268090b50ae5022e37", &large);

    var snake = LtHash.init();
    for (0..100) |index| {
        var bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &bytes, @intCast(index), .little);
        snake.add(&bytes);
    }
    snake.subtract("hello");
    try expect_checksum("e8b4c14ba58fec98fb288f56283de3ce388d7da0d775d96861a769d6399f4d07", &snake);
}

test "lthash decode rejects short input" {
    var bytes: [lthash.size - 1]u8 = @splat(0);
    try testing.expectError(error.EndOfBuffer, codec.decode(LtHash, testing.allocator, &bytes));
}

/// The `lthash_operations` fuzz target: random operations on a stack of states, then the
/// homomorphic, subtraction, commutativity, and codec properties.
fn fuzz_operations(bytes: []const u8) !void {
    const stack_max = 8;
    var input = fuzz.Input.init(bytes);
    var stack: [stack_max]LtHash = undefined;
    stack[0] = .zero;
    var depth: usize = 1;
    const operations = input.int_in_range(0, 16);
    for (0..operations) |_| {
        const top = &stack[depth - 1];
        switch (input.int_in_range(0, 5)) {
            0 => top.add(input.take(input.int_in_range(0, 64))),
            1 => top.subtract(input.take(input.int_in_range(0, 64))),
            2 => if (depth >= 2) {
                depth -= 1;
                stack[depth - 1].combine(&stack[depth]);
            } else if (depth < stack_max) {
                stack[depth] = .zero;
                depth += 1;
            },
            3 => {
                top.reset();
                try testing.expect(top.is_zero());
            },
            4 => _ = top.checksum(),
            else => _ = top.is_zero(),
        }
    }
    const a = input.take(input.int_in_range(0, 64));
    const b = input.take(input.int_in_range(0, 64));

    var joint = LtHash.init();
    joint.add(a);
    joint.add(b);
    var separate = LtHash.init();
    separate.add(a);
    var other = LtHash.init();
    other.add(b);
    separate.combine(&other);
    try testing.expect(joint.checksum().eql(separate.checksum()));

    var swapped = LtHash.init();
    swapped.add(b);
    swapped.add(a);
    try testing.expect(joint.checksum().eql(swapped.checksum()));

    var identity = LtHash.init();
    identity.add(a);
    identity.subtract(a);
    try testing.expect(identity.is_zero());

    const top = stack[depth - 1];
    const encoded = codec.encode_fixed(LtHash, top);
    const decoded = try codec.decode(LtHash, testing.allocator, &encoded);
    try testing.expect(decoded.checksum().eql(top.checksum()));
}

/// Random bytes of length `[1, max]` from `rng`, written into `out`.
fn random_bytes(rng: *utils.rng.TestRng, out: []u8, max: usize) []u8 {
    const len = utils.rng.range_at_most(rng, usize, 1, max);
    rng.fill_bytes(out[0..len]);
    return out[0..len];
}

/// The `metamorph_lthash` fuzz target: each mutation adds and removes the same multiset, so
/// the checksum returns to its starting value.
fn fuzz_metamorph(bytes: []const u8) !void {
    var input = fuzz.Input.init(bytes);
    var rng = utils.rng.TestRng.init(input.int_in_range(0, std.math.maxInt(u64)));
    const initial = input.take(input.int_in_range(0, 64));
    const mutation = input.int_in_range(0, 4);
    const a = input.take(input.int_in_range(0, 64));
    const b = input.take(input.int_in_range(0, 64));
    const count_byte = input.int_in_range(0, 255);

    var hash = LtHash.init();
    hash.add(initial);
    const expected = hash.checksum();
    var scratch: [130][256]u8 = undefined;
    var values: [130][]u8 = undefined;
    switch (mutation) {
        0 => {
            const value = random_bytes(&rng, &scratch[0], 256);
            hash.add(value);
            hash.subtract(value);
        },
        1, 2 => {
            var hash_a = LtHash.init();
            hash_a.add(a);
            var hash_b = LtHash.init();
            hash_b.add(b);
            var negated = LtHash.init();
            negated.subtract(a);
            negated.subtract(b);
            var sum = LtHash.init();
            sum.combine(&hash_a);
            sum.combine(&hash_b);
            if (mutation == 1) {
                hash.combine(&sum);
                hash.combine(&negated);
            } else {
                hash.combine(&negated);
                hash.combine(&hash_a);
                hash.combine(&hash_b);
            }
        },
        3 => {
            const count = count_byte % 32 + 1;
            var negated = LtHash.init();
            for (0..count) |index| {
                values[index] = random_bytes(&rng, &scratch[index], 256);
                hash.add(values[index]);
            }
            for (values[0..count]) |value| negated.subtract(value);
            hash.combine(&negated);
        },
        else => {
            const count = count_byte % 128 + 2;
            for (0..count) |index| {
                values[index] = random_bytes(&rng, &scratch[index], 256);
                hash.add(values[index]);
            }
            var index = count - 1;
            while (index > 0) : (index -= 1) {
                const other = utils.rng.range_at_most(&rng, usize, 0, index);
                std.mem.swap([]u8, &values[index], &values[other]);
            }
            for (values[0..count]) |value| hash.subtract(value);
        },
    }
    try testing.expect(hash.checksum().eql(expected));
    hash.reset();
    try testing.expect(hash.is_zero());
}

test "lthash fuzz (seeded)" {
    var random = fuzz.prng(0x17ba54);
    var bytes: [512]u8 = undefined;
    for (0..fuzz.iterations(64)) |_| {
        random.random().bytes(&bytes);
        const input = bytes[0..random.random().uintAtMost(usize, bytes.len)];
        try fuzz_operations(input);
        try fuzz_metamorph(input);
    }
}

test "lthash fuzz (coverage-guided)" {
    try testing.fuzz({}, struct {
        fn run(_: void, smith: *testing.Smith) anyerror!void {
            var bytes: [512]u8 = undefined;
            const length = smith.slice(&bytes);
            try fuzz_operations(bytes[0..length]);
            try fuzz_metamorph(bytes[0..length]);
        }
    }.run, .{});
}
